JavaScript:
/*:
 * @target MZ
 * @plugindesc Custom Choices with Extra Windows Plugin
 * @help This plugin allows you to create custom choice windows with extra windows that display variable values.
 *
 * @param Choices
 * @type text[]
 * @desc List of choices to display.
 * @default ["Choice 1", "Choice 2", "Choice 3"]
 *
 * @param Columns
 * @type number
 * @min 1
 * @desc Number of columns in the choice window.
 * @default 8
 *
 * @param Window Width
 * @type number
 * @desc Width of the choice window.
 * @default 600
 *
 * @param Window Height
 * @type number
 * @desc Height of the choice window.
 * @default 350
 *
 * @param Transparent Alpha
 * @type number
 * @min 0
 * @max 255
 * @desc Alpha value for transparent choices (0-255).
 * @default 128
 *
 * @param Text Opacity
 * @type number
 * @min 0
 * @max 255
 * @desc Opacity of the choice name text (0-255).
 * @default 255
 *
 * @param ExtraWindows
 * @type struct<ExtraWindow>[]
 * @desc List of extra windows to display.
 * @default []
 */

/*~struct~ExtraWindow:
 * @param x
 * @type number
 * @desc X position of the extra window.
 * @default 0
 *
 * @param y
 * @type number
 * @desc Y position of the extra window.
 * @default 0
 *
 * @param width
 * @type number
 * @desc Width of the extra window.
 * @default 200
 *
 * @param height
 * @type number
 * @desc Height of the extra window.
 * @default 100
 *
 * @param content
 * @type string
 * @desc Content to display in the extra window.
 * @default "Attack: \\V[605]"
 *
 * @param opacity
 * @type number
 * @min 0
 * @max 255
 * @desc Opacity level of the extra window (0-255).
 * @default 255
 */

(() => {
    const parameters = PluginManager.parameters('CustomChoices');
    let choices = JSON.parse(parameters['Choices']);
    const columns = Number(parameters['Columns'] || 8);
    const windowWidth = Number(parameters['Window Width'] || 600);
    const windowHeight = Number(parameters['Window Height'] || 350);
    const transparentAlpha = Number(parameters['Transparent Alpha'] || 128); // Default to semi-transparent
    const extraWindows = JSON.parse(parameters['ExtraWindows'] || '[]').map(e => JSON.parse(e));

    // Extend the Window_Command to create a custom choice window
    class Window_CustomChoices extends Window_Command {
        initialize(rect) {
            super.initialize(rect);
            this._lastVariable899Value = $gameVariables.value(899);
            this.setupVariableChangeListener();
            this._extraWindows = []; // Initialize _extraWindows array
            this.openness = 0;
            this.deactivate();
        }

        setupVariableChangeListener() {
            $gameVariables.onChange(899, this.onVariable899Change.bind(this));
        }

        onVariable899Change(newValue) {
            if (newValue !== this._lastVariable899Value) {
                this._lastVariable899Value = newValue;
                console.log(`Variable 899 changed to: ${newValue}`);

                // Update enemy stats and log their values
                if (this.updateEnemyStats()) {
                    console.log("Enemy stats updated.");
                }

                if (this.logEnemyStats()) {
                    console.log("Enemy stats logged.");
                }

                if (this.refreshExtraWindows()) {
                    console.log("Extra windows refreshed.");
                }
            }
        }

        logEnemyStats() {
            console.log(`Variable 605 (Attack): ${$gameVariables.value(605)}`);
            console.log(`Variable 606 (Defense): ${$gameVariables.value(606)}`);
            console.log(`Variable 607 (Agility): ${$gameVariables.value(607)}`);
            console.log(`Variable 608 (Magic Attack): ${$gameVariables.value(608)}`);
            console.log(`Variable 609 (Magic Defense): ${$gameVariables.value(609)}`);
            console.log(`Variable 848 (Enemy Name): ${$gameVariables.value(848)}`);
        }

        refreshExtraWindows() {
            if (this._extraWindows) { // Check if _extraWindows is defined
                this._extraWindows.forEach(window => {
                    window.refreshContent();
                });
                return true; // Indicate that extra windows were refreshed
            } else {
                console.log("_extraWindows is not defined.");
                return false; // Indicate that no extra windows were refreshed
            }
        }

        makeCommandList() {
            choices.forEach((choice, index) => {
                if (choice.trim() === '\\blocksquare') {
                    this.addCommand(' ', 'choice', false); // Add a non-selectable space
                } else {
                    this.addCommand(choice, 'choice', true, index + 1); // Add selectable choices
                }
            });
        }

        maxCols() {
            return columns;
        }

        windowWidth() {
            return windowWidth;
        }

        windowHeight() {
            return windowHeight;
        }
itemRect(index) {
    const rect = super.itemRect(index);
    const commandName = this.commandName(index);

    // Increase height by 5 pixels to create a gap
    rect.height += 48;

    const col = index % this.maxCols(); // Calculate column index
    const row = Math.floor(index / this.maxCols()); // Calculate row index

    // Calculate the width of each item box based on the number of columns
    const itemWidth = Math.floor(this.contents.width / this.maxCols());

    // Calculate x and y positions
    rect.x = col * itemWidth; // Adjust horizontal spacing as needed (here, 12 pixels between columns)
    rect.y = row * rect.height; // Create 5-pixel gap between rows

    // Set the width of the item box to be the same as calculated item width
    rect.width = itemWidth;

    if (commandName === ' ') {
        return new Rectangle(rect.x, rect.y, 0, 0); // Make "\blocksquare" choice transparent
    }

    return rect;
}


drawItem(index) {
    const rect = this.itemRect(index);
    const commandName = this.commandName(index);
    this.resetTextColor();
    this.changePaintOpacity(this.isCommandEnabled(index));

    if (commandName !== null) {
        if (commandName === ' ') {
            const alpha = transparentAlpha / 255;
            const color = 'rgba(0, 0, 0, ' + alpha + ')';
            this.contents.fillRect(rect.x, rect.y, rect.width, rect.height, color);
        } else {
            const faceFilename = `${index}`; // Adjust based on your naming convention

            const faceBitmap = ImageManager.loadBitmap('img/pictures/select/faces/', faceFilename, 0, true);

            if (faceBitmap.isReady()) {
                // Calculate the scaling factor to fit the picture width to the rect width
                const scaleX = rect.width / faceBitmap.width;
                const scaledWidth = rect.width;
                const scaledHeight = faceBitmap.height * scaleX;
                const pictureX = rect.x;
                const pictureY = rect.y;

                this.contents.blt(faceBitmap, 0, 0, faceBitmap.width, faceBitmap.height, pictureX, pictureY, scaledWidth, scaledHeight);

                // Draw choice text
                const textHeight = this.lineHeight();
                const text = commandName;
                const textWidth = this.textWidth(text);
                const offsetX = (rect.width - textWidth) / 2;
                const offsetY = rect.y + scaledHeight + 5; // Offset to position below the image

                // Set text opacity
                const textOpacity = parameters['Text Opacity'] || 255;
                this.contents.paintOpacity = textOpacity;

                this.contents.drawText(text, rect.x + offsetX, offsetY, rect.width, textHeight, 'center');

                // Reset paint opacity
                this.contents.paintOpacity = 255;
            } else if (faceBitmap.isError()) {
                console.error(`Failed to load image for index ${index} (${faceFilename})`);
            } else {
                faceBitmap.addLoadListener(() => {
                    if (faceBitmap.isError()) {
                        console.error(`Failed to load image for index ${index} (${faceFilename})`);
                    } else {
                        // Calculate the scaling factor to fit the picture width to the rect width
                        const scaleX = rect.width / faceBitmap.width;
                        const scaledWidth = rect.width;
                        const scaledHeight = faceBitmap.height * scaleX;
                        const pictureX = rect.x;
                        const pictureY = rect.y;

                        this.contents.blt(faceBitmap, 0, 0, faceBitmap.width, faceBitmap.height, pictureX, pictureY, scaledWidth, scaledHeight);

                        // Draw choice text
                        const textHeight = this.lineHeight();
                        const text = commandName;
                        const textWidth = this.textWidth(text);
                        const offsetX = (rect.width - textWidth) / 2;
                        const offsetY = rect.y + scaledHeight + 5; // Offset to position below the image

                        // Set text opacity
                        const textOpacity = parameters['Text Opacity'] || 255;
                        this.contents.paintOpacity = textOpacity;

                        this.contents.drawText(text, rect.x + offsetX, offsetY, rect.width, textHeight, 'center');

                        // Reset paint opacity
                        this.contents.paintOpacity = 255;
                    }
                });
            }
        }
    }
}


