        // Override cursorRight to skip over non-selectable items
        cursorRight(wrap) {
            const index = this.index();
            let newIndex = index;
            do {
                newIndex++;
                if (newIndex >= this.maxItems()) {
                    if (wrap) {
                        newIndex = 0;
                    } else {
                        newIndex = index;
                        break;
                    }
                }
            } while (!this.isCommandEnabled(newIndex));
            this.select(newIndex);
        }

        // Override cursorLeft to skip over non-selectable items
        cursorLeft(wrap) {
            const index = this.index();
            let newIndex = index;
            do {
                newIndex--;
                if (newIndex < 0) {
                    if (wrap) {
                        newIndex = this.maxItems() - 1;
                    } else {
                        newIndex = index;
                        break;
                    }
                }
            } while (!this.isCommandEnabled(newIndex));
            this.select(newIndex);
        }

        // Override cursorDown to skip over non-selectable items
        cursorDown(wrap) {
            const index = this.index();
            let newIndex = index;
            do {
                newIndex += this.maxCols();
                if (newIndex >= this.maxItems()) {
                    if (wrap) {
                        newIndex %= this.maxItems();
                    } else {
                        newIndex = index;
                        break;
                    }
                }
            } while (!this.isCommandEnabled(newIndex));
            this.select(newIndex);
        }

        // Override cursorUp to skip over non-selectable items
        cursorUp(wrap) {
            const index = this.index();
            let newIndex = index;
            do {
                newIndex -= this.maxCols();
                if (newIndex < 0) {
                    if (wrap) {
                        newIndex += this.maxItems();
                    } else {
                        newIndex = index;
                        break;
                    }
                }
            } while (!this.isCommandEnabled(newIndex));
            this.select(newIndex);
        }
    }


class Window_Extra extends Window_Base {
    initialize(rect, content) {
        super.initialize(rect);
        this._content = content;
        this.refreshContent(); // Initial content refresh
    }

    refreshContent() {
        this.contents.clear(); // Clear previous contents before drawing new content

        // Parse and convert the content
        const parsedContent = this.parseContent(this._content);
        const processedContent = this.convertEscapeCharacters(parsedContent);

        // Measure the width of the processed content text
        const textWidth = this.textWidthEx(processedContent);

        // Calculate the x-coordinate to center align the text based on the window width
        const centerX = (this.contents.width - textWidth) / 2;

        // Log centerX calculation to console
        console.log(`CenterX Calculation:
            Window Width: ${this.contents.width},
            Text Width: ${textWidth},
            CenterX: ${centerX}`);

        this.drawTextEx(processedContent, centerX, 0); // Use centerX for centering text
    }

    parseContent(content) {
        // Replace variable placeholders with their actual values
        return content.replace(/\\V\[(\d+)\]/gi, (_, varId) => {
            const value = $gameVariables.value(Number(varId));
            return value !== undefined ? String(value) : '';
        });
    }

    convertEscapeCharacters(text) {
        // Convert escape characters to their actual values
        text = text.replace(/\\/g, '\x1b');
        text = text.replace(/\x1b\x1b/g, '\\');
        text = text.replace(/\x1bV\[(\d+)\]/gi, (_, varId) => {
            const value = $gameVariables.value(Number(varId));
            return value !== undefined ? String(value) : '';
        });
        text = text.replace(/\x1bN\[(\d+)\]/gi, (_, actorId) => {
            const actor = $gameActors.actor(Number(actorId));
            return actor ? actor.name() : '';
        });
        text = text.replace(/\x1bP\[(\d+)\]/gi, (_, partyIndex) => {
            const actor = $gameParty.members()[Number(partyIndex) - 1];
            return actor ? actor.name() : '';
        });
        text = text.replace(/\x1bG/gi, TextManager.currencyUnit);
        // Add more escape code conversions if needed
        return text;
    }

    textWidthEx(text) {
        // Create a temporary Bitmap object to measure the text width
        const bitmap = new Bitmap();
        bitmap.fontFace = this.contents.fontFace;
        bitmap.fontSize = this.contents.fontSize;
        bitmap.fontBold = this.contents.fontBold;
        bitmap.fontItalic = this.contents.fontItalic;

        // Remove all escape codes for width measurement
        const cleanedText = text.replace(/\x1b\[\d+\]/g, '')
                                .replace(/\x1b[\{\}]/g, '')
                                .replace(/\x1b[A-Z]+\[\d*\]/gi, '')
                                .replace(/\x1b[A-Z]/gi, '');

        // Measure the width of the cleaned text
        const width = bitmap.measureTextWidth(cleanedText);

        // Log the text width for debugging
        console.log(`Measured text width: ${width} for text: ${cleanedText}`);

        return width;
    }
}




    // Add a new Scene to handle custom choices
    class Scene_CustomChoices extends Scene_MenuBase {
create() {
