    // Create windows in the desired order
    const picturesWindow = this.createPictures(); // Bottom layer

    const nameplateWindow = this.createNameplate(); // Layer above pictures

    const extraWindowsWindow = this.createExtraWindows(); // Layer above nameplate

    const customChoicesWindow = this.createCustomChoicesWindow(); // Top layer

    // Add windows to the scene
    if (picturesWindow) this.addChild(picturesWindow);

    if (nameplateWindow) this.addChild(nameplateWindow);

    if (extraWindowsWindow) this.addChild(extraWindowsWindow);

    if (customChoicesWindow) this.addChild(customChoicesWindow);
}


        createBackground() {
            // Do not call super.createBackground to avoid dimming
            this._backgroundSprite = new Sprite();
            this._backgroundSprite.bitmap = SceneManager.backgroundBitmap();
            this.addChild(this._backgroundSprite);
        }

createPictures() {
    // Create window for picture 2 (swap with picture 1)
    const rect2 = this.picture2WindowRect();
    this._pictureWindow2 = new Window_Base(rect2);
    this.addChild(this._pictureWindow2);

    // Create window for picture 1 (swap with picture 2)
    const rect1 = this.picture1WindowRect();
    this._pictureWindow1 = new Window_Base(rect1);
    this.addChild(this._pictureWindow1);

