        variableMod = "cpw3";
    } else if ([20, 28, 37, 46, 50, 57].includes(variableValue)) {
        variableMod = "cpw4";
    } else if ([3, 9, 15, 35, 58].includes(variableValue)) {
        variableMod = "redacted";
    } else if ([4, 25, 34, 47, 51, 56].includes(variableValue)) {
        variableMod = "nats";
    } else if ([5, 22, 53, 55, 18].includes(variableValue)) {
        variableMod = "rcp";
    } else if ([6, 8, 33, 38, 39].includes(variableValue)) {
        variableMod = "unified1";
    } else if ([17, 24, 29, 41, 43, 49].includes(variableValue)) {
        variableMod = "unified2";
    } else if ([26, 42, 45, 30].includes(variableValue)) {
        variableMod = "gc1";
    } else if ([11, 21, 31, 32, 48, 59, 63, 65, 66].includes(variableValue)) {
        variableMod = "world";
    } else {
        variableMod = "cpw1"; // Fallback if no match
    }

    // File paths for the primary images
    const folderPath1 = 'img/pictures/select/';
    const filename1 = `${variableValue}`;
    const bitmap1 = ImageManager.loadBitmap(folderPath1, filename1, 0, true);

    const folderPath2 = 'img/pictures/select/';
    const filename2 = '0';
    const bitmap2 = ImageManager.loadBitmap(folderPath2, filename2, 0, true);

    // File paths for the secondary images (background images)
    const backgroundFolderPath1 = 'img/pictures/select/flags/L/';
    const backgroundFilename1 = 'cpw2';
    const backgroundBitmap1 = ImageManager.loadBitmap(backgroundFolderPath1, backgroundFilename1, 0, true);

    const backgroundFolderPath2 = 'img/pictures/select/flags/R/';
    const backgroundBitmap2 = ImageManager.loadBitmap(backgroundFolderPath2, variableMod, 0, true);

    // Handle bitmap loading and drawing for picture window 1
    bitmap1.addLoadListener(() => {
        if (bitmap1.isError()) {
            const defaultBitmap1 = ImageManager.loadBitmap(folderPath1, '0', 0, true);
            defaultBitmap1.addLoadListener(() => {
                backgroundBitmap2.addLoadListener(() => {
                    this.drawPictureInWindow(backgroundBitmap2, this._pictureWindow1, true);
                    this.drawPictureInWindow(defaultBitmap1, this._pictureWindow1, false);
                    this.positionPictures(); // Ensure positions are updated after loading
                });
            });
        } else {
            backgroundBitmap2.addLoadListener(() => {
                this.drawPictureInWindow(backgroundBitmap2, this._pictureWindow1, true);
                this.drawPictureInWindow(bitmap1, this._pictureWindow1, false);
                this.positionPictures(); // Ensure positions are updated after loading
            });
        }
    });

    // Handle bitmap loading and drawing for picture window 2
    bitmap2.addLoadListener(() => {
        backgroundBitmap1.addLoadListener(() => {
            this.drawPictureInWindow(backgroundBitmap1, this._pictureWindow2, true);
            this.drawPictureInWindow(bitmap2, this._pictureWindow2, false);
            this.positionPictures(); // Ensure positions are updated after loading
        });
    });
}

positionPictures() {
    const windowWidth = 720;
    const totalWidth = windowWidth * 2; // Two windows side by side

    if (this._pictureWindow2) {
        this._pictureWindow2.x = (Graphics.boxWidth - totalWidth) / 2;
        this._pictureWindow2.y = 40;
    }

    if (this._pictureWindow1) {
        this._pictureWindow1.x = this._pictureWindow2.x + windowWidth;
        this._pictureWindow1.y = 40;
    }
}

drawPictureInWindow(bitmap, window, isBackground) {
    if (window && bitmap) {
        if (isBackground) {
            // Clear the contents and draw the background image
            window.contents.clear();
        }
        window.opacity = 0;

        // Calculate new dimensions for 95% scaling
        const scaledWidth = bitmap.width * 0.95;
        const scaledHeight = bitmap.height * 0.95;

        // Calculate position to center the scaled bitmap within the window
        const offsetX = (window.contentsWidth() - scaledWidth) / 2;
        const offsetY = (window.contentsHeight() - scaledHeight) / 2;

        // Draw the bitmap with scaling and centered position
        window.contents.blt(bitmap, 0, 0, bitmap.width, bitmap.height, offsetX, offsetY, scaledWidth, scaledHeight);
    }
}

picture1WindowRect() {
