picture2WindowRect() {
    const windowWidth = 720;
    const windowHeight = 720;
    const wx = (Graphics.boxWidth + windowWidth * 2) / 2; // Center horizontally
    const wy = 40; // Fixed y position
    return new Rectangle(wx, wy, windowWidth, windowHeight);
}



