                const window = new Window_Extra(rect, extraWindow.content); // Pass content to the window

        window.opacity = Number(extraWindow.opacity); // Set opacity from parameter

                window.refreshContent(); // Refresh content initially
                this._extraWindows.push(window); // Push the window instance into _extraWindows array
                this.addChild(window); // Add the window to the scene
            });
